export const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export const fields=[['name','Nome do negócio',['nome / clinica','nome','nome da empresa','empresa','clinica','name','negocio']],['category','Categoria',['categoria','category','segmento']],['district','Bairro',['bairro','district']],['city','Cidade',['cidade','city']],['address','Endereço',['endereco','address']],['phone','Telefone',['telefone','phone','whatsapp','celular']],['rating','Nota no Google',['nota (google)','nota','avaliacao','rating']],['reviews','Número de avaliações',['nº de avaliacoes','n° de avaliacoes','no de avaliacoes','numero de avaliacoes','avaliacoes','reviews']],['maps','Google Maps',['link no google maps','google maps','maps','link google maps']],['instagram','Instagram',['instagram','insta']],['email','E-mail',['e-mail','email']],['website','Site',['site','website','url do site']]].map(([key,label,aliases])=>({key,label,aliases}));
export function safeUrl(value){if(!value)return '';try{const u=new URL(String(value).trim());return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
export function phoneLink(value){const raw=String(value||'');let n=raw.replace(/\D/g,'');if(n.length===10||n.length===11)n='55'+n;return n.length>=12&&n.length<=15?'https://wa.me/'+n:''}
export function dedupeKey(l){return normalize(l.name)+'|'+normalize(l.city)+'|'+String(l.phone||'').replace(/\D/g,'').replace(/^55(?=\d{10,11}$)/,'')}

export function instagramUrl(value){const v=String(value||'').trim();if(!v)return '';if(/^https?:\/\//i.test(v))return safeUrl(v);const handle=v.replace(/^@/,'').replace(/\/$/,'');return /^[a-zA-Z0-9._]{1,30}$/.test(handle)?'https://www.instagram.com/'+handle+'/':''}
